import{_ as a,o as r,c as o,a7 as t}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Birthday Buddy Support","description":"Official support information for Birthday Buddy.","frontmatter":{"title":"Birthday Buddy Support","description":"Official support information for Birthday Buddy.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/birthday-buddy.md","filePath":"support/birthday-buddy.md"}'),i={name:"support/birthday-buddy.md"};function n(s,e,l,d,c,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="birthday-buddy-support" tabindex="-1">Birthday Buddy Support <a class="header-anchor" href="#birthday-buddy-support" aria-label="Permalink to &quot;Birthday Buddy Support&quot;">​</a></h1><p>Birthday Buddy keeps birthdays, anniversaries, and occasion reminders locally on your device. No account is required.</p><h2 id="reminders-are-not-appearing" tabindex="-1">Reminders are not appearing <a class="header-anchor" href="#reminders-are-not-appearing" aria-label="Permalink to &quot;Reminders are not appearing&quot;">​</a></h2><ol><li>Confirm the occasion has a reminder enabled and its date and time are correct.</li><li>Allow Birthday Buddy notifications in Android settings.</li><li>Review battery optimization, background restrictions, and exact-alarm access where your Android version exposes those controls.</li><li>Restart the app after changing system permissions. Reboot restoration is handled locally, but Android ultimately controls delivery timing.</li></ol><h2 id="contact-import-or-sync-is-unavailable" tabindex="-1">Contact import or sync is unavailable <a class="header-anchor" href="#contact-import-or-sync-is-unavailable" aria-label="Permalink to &quot;Contact import or sync is unavailable&quot;">​</a></h2><ul><li>To select one person, use the Android contact picker.</li><li>For full sync, grant contacts permission when prompted and review the preview before importing.</li><li>Birthday Buddy never edits Android Contacts. If a source contact changes, run sync again to preview supported changes.</li><li>Browser builds do not have Android&#39;s native contact-sync integration.</li></ul><h2 id="camera-or-photo-selection-is-unavailable" tabindex="-1">Camera or photo selection is unavailable <a class="header-anchor" href="#camera-or-photo-selection-is-unavailable" aria-label="Permalink to &quot;Camera or photo selection is unavailable&quot;">​</a></h2><p>Allow camera permission only if you want to take a new photo. Existing images are selected through the system picker where supported. If permission was denied permanently, enable it from Android&#39;s app settings.</p><h2 id="pin-or-biometric-unlock-problems" tabindex="-1">PIN or biometric unlock problems <a class="header-anchor" href="#pin-or-biometric-unlock-problems" aria-label="Permalink to &quot;PIN or biometric unlock problems&quot;">​</a></h2><p>Biometric unlock is optional and becomes available only after a PIN is set. Changes to enrolled biometrics or device security can invalidate the protected key; use the PIN if available and configure biometrics again. The developer cannot recover your PIN.</p><h2 id="backup-or-restore-problems" tabindex="-1">Backup or restore problems <a class="header-anchor" href="#backup-or-restore-problems" aria-label="Permalink to &quot;Backup or restore problems&quot;">​</a></h2><p>Keep the <code>.ocbackup</code> file and its exact password together securely. Backup passwords are not stored and cannot be recovered. Make a current backup before restoring because restore operations can change local data. Ensure the selected file was created by Birthday Buddy and has not been modified.</p><h2 id="clear-local-data" tabindex="-1">Clear local data <a class="header-anchor" href="#clear-local-data" aria-label="Permalink to &quot;Clear local data&quot;">​</a></h2><p>On Android, clear Birthday Buddy&#39;s storage in system settings or uninstall the app. In a browser, clear site data for <code>actionanand.github.io</code>. Exported backup files must be deleted separately from wherever you saved them.</p><h2 id="contact-support" tabindex="-1">Contact support <a class="header-anchor" href="#contact-support" aria-label="Permalink to &quot;Contact support&quot;">​</a></h2><p>Email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong> with your platform/version and reproducible steps. Do not include contacts, personal dates, photos, PINs, backup passwords, or backup files unless necessary and you understand the risk.</p>',16)])])}const b=a(i,[["render",n]]);export{h as __pageData,b as default};
